const en=document.documentElement.lang==='en',t=(zh,eng)=>en?eng:zh,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),name=p=>en?p.name:p.zh;
