const state={period:'7',mode:initialMode,query:'',category:'all',accessible:false,neutral:false,origin:{...scenarioOrigin},selected:null,guide:null,stage:0,view:'find',pick:false,reminders:true,muted:false,timer:null,snooze:null,feedback:[],stepFree:false};
