document.title=t('Clue · 校园里的每一处','Clue · Find your place');
$('#app').innerHTML=`<div class="entry-animation" id="entryAnimation" aria-hidden="true"><div class="entry-lens"></div><span>Clue<span class="red-dot">.</span></span><small>UNFOLD THE CAMPUS</small></div><header class="topbar"><a class="brand" href="#/find"><img src="assets/mark.svg" alt=""><span>Clue<span class="red-dot">.</span><small>THE CAMPUS CASEBOOK</small></span></a><nav aria-label="${t('主导航','Main navigation')}"><a data-nav="find" href="#/find">${t('线索板','The board')}</a><a data-nav="saved" href="#/saved">${t('我的收藏','Saved clues')}</a><a data-nav="about" href="#/about">${t('原型说明','Prototype notes')}</a></nav><div class="header-actions"><button id="scopeButton" class="mode-chip">${icon('info')}<span id="modeLabel">${t('设计演示','DESIGN DEMO')}</span></button><a class="language" href="${en?'zh.html':'en.html'}">${en?'中文':'EN'} ↗</a></div></header><div class="campus-strip"><span>UNIVERSITY OF BIRMINGHAM</span><span>EDGBASTON / FIELD NOTES № 01</span><span class="strip-date">${t('每个小地点，都值得被找到。','Every little place is worth finding.')}</span></div><main id="main"><div id="boardPage"><section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="tiny-cross">✳</span> A LITTLE CURIOSITY GOES A LONG WAY</p><h1>${t('循着线索，<br><em>找到去处。</em>','Follow the clue.<br><em>Find your place.</em>')}</h1><p class="hero-intro">${t('那间教室在哪层？最近的厕所在哪儿？<br>翻开校园的线索，一次找到一个小地点。','The room, the right floor, the nearest loo.<br>Unfold the campus, one little place at a time.')}</p></div><div class="hero-note pinned"><span class="note-number">01</span><p class="handwritten">${t('今天，要找哪里？','What are we looking for?')}</p><span class="note-label">ROOMS · FLOORS · LITTLE NECESSITIES</span><div class="note-rule"></div><span class="note-foot">${t('从大地图，到小地点。','From the big map to the little details.')}</span></div><div class="hero-stamp" aria-hidden="true">CAMPUS<br><b>EXPLORER</b><br>EST. 2026</div></section><div class="case-workspace"><aside class="case-file paper" aria-label="${t('地点搜索与档案','Place search and case file')}"><div class="folder-label">${t('地点档案','THE CASE FILE')}</div><div id="searchPane"><div class="file-title"><span class="eyebrow">${t('从一条线索开始','START WITH A CLUE')}</span><span class="file-star">✳</span></div><form id="searchForm" class="search-box" role="search"><label class="sr-only" for="search">${t('搜索教室、房间号码或建筑','Search rooms, room codes or buildings')}</label>${icon('search')}<input id="search" type="search" autocomplete="off" placeholder="${t('教室、房间号、厕所…','Room, code, building…')}"><button type="submit" aria-label="${t('搜索','Search')}">${icon('arrow')}</button></form><div class="categories" aria-label="${t('地点类型','Place type')}"><button data-category="all">${t('全部线索','All clues')}</button><button data-category="room">${icon('room')}${t('找教室','Rooms')}</button><button data-category="toilet">${icon('toilet')}${t('找厕所','Toilets')}</button></div><div id="filters" class="filters" hidden><label><input id="accessible" type="checkbox">${t('无障碍设施','Adapted facilities')}</label><label><input id="neutral" type="checkbox">${t('性别中立','Gender-neutral')}</label></div><div class="origin-row"><span>${icon('locate')}<span id="originLabel"></span></span><button id="changeOrigin" class="text-button">${t('更换','Change')}</button></div><div class="list-heading"><h2 id="listTitle"></h2><span id="resultCount"></span></div><div id="results" class="results"></div><p id="resultNote" class="small directory-note"></p></div><div id="detailPane" hidden></div><div id="guidePane" hidden></div></aside><section class="evidence-board" aria-label="${t('校园线索地图','Campus clue map')}"><div class="board-topline"><span><span class="red-pin"></span>${t('校园线索地图','THE CAMPUS BOARD')}</span><div class="map-tabs"><button id="outdoorTab" class="active">${t('校园地图','Campus')}</button><button id="indoorTab">${t('楼层线索','Inside')}</button></div><span class="map-demo-tag" id="mapModeTag">${t('情境演示','SCENARIO')}</span></div><div id="outdoorMap" class="map-stage"><div class="map-paper"><svg id="campusMap" viewBox="900 430 800 630" role="group" aria-label="${t('可拖动缩放的学校地图','Pannable and zoomable campus map')}"><image href="assets/campus-map.webp" x="0" y="0" width="1786" height="1263"/><g id="mapConnection"></g><g id="markers"></g><g id="originMarker"></g></svg><div class="map-compass" aria-hidden="true">N<br>↑</div><div class="map-controls"><button id="zoomIn" aria-label="${t('放大地图','Zoom in')}">＋</button><button id="zoomOut" aria-label="${t('缩小地图','Zoom out')}">−</button><button id="resetMap" aria-label="${t('重置地图','Reset map')}">⌖</button></div><div id="mapHint" class="map-hint" hidden></div></div><div class="map-memo paper"><span class="memo-pin"></span><span class="memo-heading">${t('线索备忘','FIELD NOTE')}</span><p id="mapMemo">${t('点击图钉，<br>展开那栋楼的故事。','Pick a pin.<br>Open a little possibility.')}</p><span class="memo-arrow" aria-hidden="true">↗</span></div><div class="board-thread" aria-hidden="true"></div><div class="map-credit">${t('提供的 Edgbaston Campus Map · 图钉对应建筑','Supplied Edgbaston Campus Map · pins represent buildings')}</div></div><div id="indoorMap" class="indoor-stage" hidden></div><div class="board-bottom"><div class="board-legend"><span class="legend-dot"></span>${t('建筑','Building')}<span class="legend-dot blue"></span>${t('演示起点','Scenario origin')}<span class="legend-thread"></span><span id="threadLegend">${t('线索关联（非真实路线）','Clue connection (not a real route)')}</span></div><button id="pickOrigin" class="text-button">${icon('pin')}${t('地图选起点','Set a map origin')}</button></div><div class="board-caption"><span class="caption-no">FIG. 01</span><p>${t('把“到了这栋楼”，变成“找到了这个地方”。','Turn “I found the building” into “I found the place.”')}</p><button id="exampleRoom" class="round-button" aria-label="${t('打开教室 404 档案','Open the Room 404 case file')}">${icon('arrow')}</button></div></section></div></div><section id="aboutPage" class="about-page" hidden></section></main><footer><span>Clue<span class="red-dot">.</span> ${t('留一点好奇，少一点绕路。','A little curiosity. A little less wandering.')}</span><button id="footerScope" class="text-button">${t('真实能力与设计假设','Reality & design assumptions')}</button><span>AN UNOFFICIAL STUDENT DESIGN PROTOTYPE</span></footer><button id="mobileMapToggle" class="mobile-map-toggle">${icon('pin')}${t('打开地图','Open map')}</button><div id="toast" class="toast" role="status" hidden></div><aside id="arrivalPrompt" class="arrival-prompt paper" aria-live="polite" hidden></aside><dialog id="scopeDialog" aria-labelledby="scopeTitle"><button class="dialog-close" data-close="scopeDialog" aria-label="${t('关闭','Close')}">${icon('close')}</button><p class="eyebrow">BEFORE WE OPEN THE CASE</p><h2 id="scopeTitle">${t('先说清楚，<em>再一起想象。</em>','A little clarity.<br><em>Then a little imagination.</em>')}</h2><p class="dialog-intro">${t('这是以用户体验为重点的交互设计原型。可以在假设技术完善的前提下，体验完整的找路流程。','This interactive prototype focuses on the user experience. Explore the full journey on the assumption that the supporting technology exists.')}</p><div class="scope-grid"><article><span>01 / REAL</span><h3>${t('当前真实实现','What actually works')}</h3><p>${t('搜索与筛选、学校地图、收藏、页面跳转、前端交互，以及链接的少量公开地点资料。','Search, filters, the campus map, bookmarks, page transitions, frontend interactions and a small sourced directory.')}</p></article><article><span>02 / ASSUMED</span><h3>${t('为了设计而假设','What the concept assumes')}</h3><p>${t('完整的房间与楼层数据库、室内定位、可通行路线、设施开放状态与及时的位置事件。','A complete room/floor database, indoor positioning, accessible paths, facility status and timely location events.')}</p></article><article><span>03 / SIMULATED</span><h3>${t('演示，不是真实导航','A demo, not live navigation')}</h3><p>${t('部分楼层、开放状态、热度榜、预计用时、红线路径和室内图为情境数据。没有真实定位、后台服务或消息发送，请勿据此实际找路。','Some floors, availability, popularity rankings, times, red paths and indoor plans are fictional scenarios. No live location, backend or message delivery; do not use them for real navigation.')}</p></article></div><div class="mode-choice"><label><input type="radio" name="mode" value="concept" checked><span><strong>${t('体验完整设计','Explore the full concept')}</strong><small>${t('默认 · 假设后端完善，持续显示演示标识','Default · assumed backend, persistent demo label')}</small></span></label><label><input type="radio" name="mode" value="evidence"><span><strong>${t('只查看已有资料','Inspect sourced information')}</strong><small>${t('不补充假设楼层，不显示演示路线','No invented floors or scenario routes')}</small></span></label></div><button id="acceptScope" class="primary full">${t('明白，打开线索板','Understood. Open the board')}${icon('arrow')}</button></dialog><dialog id="originDialog" aria-labelledby="originTitle"><button class="dialog-close" data-close="originDialog" aria-label="${t('关闭','Close')}">${icon('close')}</button><p class="eyebrow">SET THE SCENE</p><h2 id="originTitle">${t('线索从哪里开始？','Where does the trail begin?')}</h2><p>${t('切换演示起点来体验附近地点推荐；不会读取真实设备位置。','Choose a scenario origin to explore nearby recommendations. Device location is not read.')}</p><label class="field">${t('参考地点','Reference location')}<select id="originSelect"><option value="green">Green Heart</option>${buildings.map(b=>`<option value="${b.id}">${esc(name(b))}</option>`).join('')}</select></label><button id="setOrigin" class="primary full">${t('从这里开始','Start from here')}${icon('arrow')}</button></dialog><dialog id="feedbackDialog" aria-labelledby="feedbackTitle"><button class="dialog-close" data-close="feedbackDialog" aria-label="${t('关闭','Close')}">${icon('close')}</button><p class="eyebrow">A NOTE FOR THE NEXT EXPLORER</p><h2 id="feedbackTitle">${t('补充一条线索','Leave a little clue')}</h2><p>${t('记录哪里不清楚，帮助下一轮设计。仅保留于本次页面演示，不会提交给学校。','Note what was unclear for the next design iteration. Kept in this page session only; not submitted to the university.')}</p><label class="field">${t('观察或建议','Observation or suggestion')}<textarea id="feedbackText" rows="4" maxlength="800"></textarea></label><button id="saveFeedback" class="primary full">${t('保存演示反馈','Save demo feedback')}</button></dialog>`;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function persistSaved(){try{localStorage.setItem('clue:saved',JSON.stringify(saved));}catch{toast(t('收藏仅保留于当前页面。','Bookmarks will last for this page only.'));}}
function list(){return findPlaces(directory(),buildings,{...state,saved:state.view==='saved'?saved:null});}
function distanceText(p){const d=metres(p);return d===null?'':demo()?t('约 ','~')+walkMinutes(d,p.floor)+t(' 分钟',' min'):t('约 ','~')+Math.round(d/10)*10+' m';}
const label=p=>p.scenario?t('情境楼层','SCENARIO FLOOR'):p.source?t('有公开来源','SOURCE LINKED'):t('待核实','UNCONFIRMED');
function renderList(){const popular=isPopularContext(state),result=popular?popularPlaces(directory(),state.period):list();$('#listTitle').textContent=popular?t('热门线索 · Top 10','Trending clues · Top 10'):state.view==='saved'?t('收好的线索','Clues worth keeping'):state.query.trim()?t('匹配的地点线索','Matching place clues'):state.category==='toilet'?t('附近的厕所','Toilets nearby'):state.category==='room'?t('教室线索','Room clues'):t('地点目录','Place directory');$('#resultCount').textContent=popular?String(result.length)+' '+t('条线索','CLUES'):String(result.length).padStart(2,'0');$('#resultNote').textContent=popular?(state.period==='30'?t('近30天','Last 30 days'):t('近7天','Last 7 days'))+' · '+t('情境热度榜，非真实同学的查询统计；不收集搜索记录。','Illustrative ranking, not actual student search statistics. Queries are not collected.'):demo()?t('情境目录 · 用时与状态用于设计演示。','Scenario directory · times and status illustrate the design.'):t('试用目录；距离为到建筑的近似直线距离。','Pilot directory; approximate straight-line distances to buildings.');$('#results').innerHTML=result.length?result.map((p,i)=>'<button class="clue-card" data-place="'+p.id+'"><span class="clue-index">'+String(p.rank||i+1).padStart(2,'0')+'</span><span class="clue-copy"><small>'+esc(p.building+' / '+name(bOf(p)))+'</small><strong>'+esc(name(p))+'</strong><span class="card-meta"><span>'+esc(floor(p))+'</span><span>'+esc(distanceText(p))+(demo()?' · '+t('演示','demo'):'')+'</span></span>'+(popular?'<span class="heat-count">'+icon('search')+p.lookupCount+' '+t('次寻找 · 演示','lookups · demo')+'</span>':'')+'</span><span class="card-icon">'+icon(p.type)+'</span></button>').join(''):'<div class="empty"><span class="handwritten">'+t('线索暂未出现…','No clues here. Yet.')+'</span><p>'+t('换个关键词，或回到全部热门线索。','Try another keyword or return to the full collection.')+'</p><button id="clearSearch" class="outline">'+t('回到热门线索','Back to trending clues')+'</button></div>';$('#results').querySelectorAll('[data-place]').forEach(el=>el.onclick=()=>openPlace(el.dataset.place));$('#clearSearch')?.addEventListener('click',resetExplorer);}
function render(){const p=state.selected,g=state.guide;$('#boardPage').classList.toggle('has-case',!!p||!!g);$('#searchPane').hidden=!!p||!!g;$('#detailPane').hidden=!p||!!g;$('#guidePane').hidden=!g;$('#filters').hidden=state.category!=='toilet';$('#originLabel').textContent=(state.origin?name(state.origin):t('未设置起点','No origin'))+(demo()?t(' · 演示起点',' · scenario origin'):t(' · 参考点',' · reference'));$('#modeLabel').textContent=demo()?t('设计演示','DESIGN DEMO'):t('资料查看','SOURCE VIEW');$('#mapModeTag').textContent=demo()?t('情境演示','SCENARIO'):t('建筑点位','BUILDING POINTS');$('#threadLegend').textContent=demo()?t('线索关联／演示路线','Clue connection / scenario path'):t('仅显示建筑位置','Building positions only');document.querySelectorAll('[data-category]').forEach(el=>{const active=el.dataset.category===state.category;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active);});document.querySelectorAll('[data-nav]').forEach(a=>a.setAttribute('aria-current',a.dataset.nav===state.view?'page':'false'));if(!p&&!g)renderList();if(p&&!g)renderDetail();if(g)renderGuide();renderMap();decorateScene({view:state.view,place:state.guide||state.selected,stage:state.guide?state.stage:-1,saved,places:directory(),buildings,mode:state.mode,en,onExplore:()=>{state.query='';state.category='all';state.accessible=false;state.neutral=false;state.selected=null;state.view='find';$('#search').value='';$('#accessible').checked=false;$('#neutral').checked=false;location.hash='/find';render();},onSave:id=>{if(!saved.includes(id))saved.push(id);persistSaved();render();}});refreshExplorer({en,view:state.view,place:state.selected,guide:state.guide,stage:state.stage,period:state.period,popular:isPopularContext(state),query:state.query,category:state.category});}
function saveButton(p){return `<button id="savePlace" class="save-button ${saved.includes(p.id)?'saved':''}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?t('取消收藏','Unsave place'):t('收藏地点','Save place')}">${icon('bookmark')}${saved.includes(p.id)?t('已收藏','Saved'):t('收藏','Save')}</button>`;}
function sourceInfo(p){const original=places.find(x=>x.id===p.id);return `<details class="source-details"><summary>${t('查看真实资料与演示假设','Real sources & scenario assumptions')}</summary><p>${demo()?t('当前为设计演示。部分楼层、设施状态、路径与耗时采用假设数据，不用于真实找路。','This is a design demonstration. Some floors, availability, paths and times are assumed, not real navigation.'):t('当前为资料查看模式，不补充未知楼层。','Source view does not fill in unknown floors.')}</p><p>${t('原始目录楼层：','Original directory floor: ')}${esc(floorName(original.floor,en))}</p>${original.source?`<a href="${sources[original.source].url}" target="_blank" rel="noopener">${sources[original.source].name} ↗</a><p>${t('查阅日期','Consulted')} ${checked} · ${t('公开来源不等于现场复核。','A public source is not a field check.')}</p>`:`<p>${t('原始房间标签来自前期原型，尚需核验。','The original room label comes from the previous prototype and needs verification.')}</p>`}</details>`;}
function renderDetail(){const p=state.selected,b=bOf(p);$('#detailPane').innerHTML=`<div class="detail-toolbar"><button id="backToList" class="text-button">← ${t('返回线索','Back to clues')}</button>${saveButton(p)}</div><p class="eyebrow">CASE / ${esc(p.id.toUpperCase())}</p><div class="place-kind">${icon(p.type)}${p.type==='room'?t('教室档案','ROOM FILE'):t('设施档案','FACILITY FILE')}</div><h2 class="place-title">${esc(name(p))}</h2><p class="building-line">${esc(b.id+' · '+name(b))}</p><div class="floor-ticket"><span>${t('关键线索：楼层','THE KEY CLUE: FLOOR')}</span><strong>${esc(floor(p))}</strong><small>${esc(label(p))} ${demo()?' / '+t('英国楼层标识','UK FLOOR LABELS'):''}</small><span class="ticket-cut"></span></div><div class="place-facts"><div><span>${demo()?t('从演示起点到地点','FROM SCENARIO ORIGIN'):t('距参考起点','FROM REFERENCE ORIGIN')}</span><strong>${esc(distanceText(p))}${demo()?' · '+t('演示','demo'):''}</strong></div><div><span>${t('设施与通行','FACILITIES & ACCESS')}</span><strong>${demo()?t('可前往 · 情境假设','Available · scenario'):t('现场状态待核对','Access not confirmed')}</strong></div></div>${p.type==='toilet'?`<div class="facility-tags">${p.accessible?`<span>♿ ${t('无障碍设施','Adapted facilities')}</span>`:''}${p.genderNeutral?`<span>${t('性别中立','Gender-neutral')}</span>`:''}</div>`:''}<p class="detail-note">${demo()?t('一栋楼、一层楼、一块门牌。把线索连起来，找到具体地点。','A building. A floor. A door sign. Connect the little clues to the place.'):esc(p.note[en?1:0])}</p><button id="startGuide" class="primary full">${demo()?t('前往这里（演示）','Go here (demo)'):t('查看地点引导','Open place guidance')}${icon('arrow')}</button>${demo()?`<label class="reminder-choice"><input id="reminderChoice" type="checkbox" ${state.reminders?'checked':''}>${t('体验接近建筑时的主动提醒（演示）','Try proactive building-approach prompts (demo)')}</label>`:''}${sourceInfo(p)}`;$('#backToList').onclick=()=>{state.selected=null;location.hash='/'+state.view;render();};$('#savePlace').onclick=()=>{saved=saved.includes(p.id)?saved.filter(id=>id!==p.id):[...saved,p.id];persistSaved();renderDetail();};$('#reminderChoice')?.addEventListener('change',e=>state.reminders=e.target.checked);$('#startGuide').onclick=()=>{state.guide=p;state.stage=0;state.muted=false;state.stepFree=false;location.hash='/guide/'+p.id;render();if(demo()&&state.reminders)queuePrompt(8000);};}
function stopTimers(){clearTimeout(state.timer);clearTimeout(state.snooze);state.timer=null;state.snooze=null;}
function queuePrompt(ms){clearTimeout(state.timer);state.timer=setTimeout(()=>{if(state.guide&&state.stage===0&&!state.muted&&demo())showPrompt();},ms);}
function showPrompt(){if(!state.guide||state.muted)return;const p=state.guide;$('#arrivalPrompt').hidden=false;$('#arrivalPrompt').innerHTML=`<div class="prompt-mark">${icon('bell')}</div><div><p class="eyebrow">${t('新线索 · 模拟位置事件','NEW CLUE · SIMULATED LOCATION EVENT')}</p><h2>${t('快到这栋楼了。','The building is just ahead.')}</h2><p>${esc(name(bOf(p)))} · ${t('接下来找','Next, find')} ${esc(floor(p))}</p><p class="small">${t('这是一条主动提醒的情境演示，没有读取真实位置。','A proactive prompt scenario; no real device location was read.')}</p><div class="prompt-actions"><button id="promptGo" class="primary">${t('展开楼层线索','Open floor clue')}</button><button id="promptSnooze" class="text-button">${t('稍后 5 分钟','Snooze 5 min')}</button><button id="promptMute" class="text-button">${t('本次静音','Mute this case')}</button></div></div>`;$('#promptGo').onclick=()=>{state.stage=1;$('#arrivalPrompt').hidden=true;render();switchMap(true);};$('#promptSnooze').onclick=()=>{$('#arrivalPrompt').hidden=true;state.snooze=setTimeout(()=>{if(state.guide&&state.stage===0&&!state.muted)showPrompt();},300000);toast(t('本次演示提醒已稍后处理，可随时继续。','Prompt snoozed. Continue whenever ready.'));};$('#promptMute').onclick=()=>{state.muted=true;stopTimers();$('#arrivalPrompt').hidden=true;renderGuide();};}
function renderGuide(){const p=state.guide,b=bOf(p);$('#guidePane').innerHTML=`<div class="detail-toolbar"><span class="eyebrow">${t('线索追踪','FOLLOWING A CLUE')}</span><button id="endGuide" class="text-button">${t('结束','End')}</button></div><h2 class="place-title">${esc(name(p))}</h2><p class="building-line">${esc(name(b))} · ${esc(floor(p))}</p><div class="stepper">${[t('到建筑','Building'),t('找楼层','Floor'),t('到地点','Place')].map((s,i)=>`<span class="${state.stage===i?'current':state.stage>i?'done':''}"><b>${state.stage>i?'✓':'0'+(i+1)}</b>${s}</span>`).join('')}</div><div class="route-instruction"><p class="eyebrow">${demo()?t('情境导航','SCENARIO GUIDANCE'):t('资料引导','SOURCE GUIDANCE')} / 0${state.stage+1}</p><h3>${state.stage===0?t('先循着线索，找到这栋楼。','First clue: the right building.'):state.stage===1?t('下一条线索，在这一层。','Next clue: the right floor.'):t('最后，核对这块门牌。','Last clue: the right door.')}</h3>${state.stage===0?`<div class="route-ticket"><span>${icon('pin')}${esc(state.origin?name(state.origin):'Green Heart')}</span><span class="ticket-thread">↓</span><strong>${esc(b.id+' · '+name(b))}</strong><small>${demo()?esc(distanceText(p))+' · '+t('演示预计','scenario estimate'):t('参照校园地图查找建筑','Locate the building on the campus map')}</small></div><p>${demo()?t('红线展示假设导航服务返回的示例连接。到楼时，系统会将重点切换到楼层与房间。','The red thread represents an assumed navigation service’s example path. On approach, the focus shifts to the floor and room.'):t('仅显示近似建筑点位，不生成未经核验的路线。','Approximate building points only; no unverified path is generated.')}</p><button id="enterBuilding" class="primary full">${t('进入建筑','Enter the building')}${demo()?t('（演示）',' (demo)'):''}${icon('arrow')}</button>${demo()?`<div class="guide-controls"><button id="replayPrompt" class="text-button">${icon('bell')}${t('播放到楼提醒','Play approach prompt')}</button><button id="muteGuide" class="text-button">${state.muted?t('恢复提醒','Resume prompts'):t('暂停提醒','Pause prompts')}</button></div>`:''}`:state.stage===1?`<div class="floor-ticket compact"><span>${t('目标楼层','DESTINATION FLOOR')}</span><strong>${esc(floor(p))}</strong><small>${esc(label(p))}</small></div><p>${demo()?t('楼层图将电梯、楼梯和目的地点放在一起。选择通行偏好，路线随之调整。','The floor sketch connects the lift, stairs and destination. Choose an access preference to adapt the concept path.'):t('请按有来源的楼层信息与现场标识查找；未知楼层需现场确认。','Use the sourced floor and on-site signs; confirm unknown floors locally.')}</p>${demo()?`<label class="step-free-choice"><input id="stepFree" type="checkbox" ${state.stepFree?'checked':''}>${t('优先电梯与无台阶路径（演示）','Prefer lift and step-free path (demo)')}</label>`:''}<button id="atFloor" class="primary full">${t('到达楼层，继续找地点','At the floor. Find the place')}${icon('arrow')}</button>`:`<div class="found-ticket">${icon(p.type)}<span>${esc(floor(p))}</span><strong>${esc(name(p))}</strong><small>${t('建筑 → 楼层 → 地点','BUILDING → FLOOR → PLACE')}</small></div><p>${demo()?t('用房间号和门牌作最后一次确认。校园地图里的一个点，现在有了具体的去处。','Check the room code and door sign one last time. A point on the campus map becomes a place to arrive at.'):esc(p.note[en?1:0])}</p><button id="finishGuide" class="primary full">${icon('check')}${t('找到了，结案。','Found it. Case closed.')}</button><button id="leaveFeedback" class="text-button feedback-link">${t('留下一条反馈线索','Leave a feedback clue')}</button>`}</div>`;
 $('#endGuide').onclick=endGuide;$('#enterBuilding')?.addEventListener('click',()=>{stopTimers();state.stage=1;$('#arrivalPrompt').hidden=true;render();switchMap(true);});$('#atFloor')?.addEventListener('click',()=>{state.stage=2;render();switchMap(true);});$('#stepFree')?.addEventListener('change',e=>{state.stepFree=e.target.checked;renderIndoor();});$('#finishGuide')?.addEventListener('click',()=>{const p=state.guide;stopTimers();state.guide=null;state.selected=p;$('#arrivalPrompt').hidden=true;location.hash='/place/'+p.id;render();switchMap(false);toast(t('地点已找到。保留一点好奇，留给下一次探索。','Case closed. Keep a little curiosity for the next one.'));});$('#leaveFeedback')?.addEventListener('click',()=>$('#feedbackDialog').showModal());$('#replayPrompt')?.addEventListener('click',()=>{state.muted=false;showPrompt();});$('#muteGuide')?.addEventListener('click',()=>{state.muted=!state.muted;stopTimers();$('#arrivalPrompt').hidden=true;if(!state.muted)queuePrompt(8000);renderGuide();});}
function endGuide(){stopTimers();state.guide=null;$('#arrivalPrompt').hidden=true;location.hash='/place/'+state.selected.id;render();switchMap(false);}
function resetExplorer(){stopTimers();state.guide=null;state.selected=null;state.query='';state.category='all';state.accessible=false;state.neutral=false;state.view='find';$('#search').value='';$('#accessible').checked=false;$('#neutral').checked=false;$('#arrivalPrompt').hidden=true;location.hash='/find';render();switchMap(false);showExplorerList();}
function focusDestination(building){const mobile=matchMedia('(max-width:800px)').matches,width=630,height=width*630/800;tweenMap(svg,[building.x-width*(mobile ? 0.5 : 0.65),building.y-height*(mobile ? 0.28 : 0.45),width,height],next=>{box=next;setBox();});}
function openPlace(id,source='list'){const p=byId(id);if(!p)return;traceSelection({place:p,building:bOf(p),en,source});stopTimers();state.guide=null;state.selected=p;$('#arrivalPrompt').hidden=true;$('#boardPage').classList.remove('mobile-map-open');mobileMapLabel(false);location.hash='/place/'+id;render();switchMap(false);focusDestination(bOf(p));}
function showBuilding(id){if(state.guide){toast(t('可结束当前演示，再选择新的地点。','End this demonstration before selecting another place.'));return;}const group=directory().filter(p=>p.building===id);if(group.length===1){openPlace(group[0].id,'map');return;}state.view='find';state.selected=null;state.query=id;state.category='all';state.accessible=false;state.neutral=false;$('#search').value=id;$('#accessible').checked=false;$('#neutral').checked=false;location.hash='/find';render();showExplorerList();focusDestination(buildings.find(b=>b.id===id));}
const svg=$('#campusMap');let box=[900,430,800,630],drag=null,moved=false,pinch=null,pointers=new Map();
function setBox(){svg.setAttribute('viewBox',box.join(' '));}
function zoom(f){stopMapTween(svg);const width=Math.max(220,Math.min(1550,box[2]*f)),height=width*630/800;box=[box[0]+(box[2]-width)/2,box[1]+(box[3]-height)/2,width,height];setBox();}
$('#zoomIn').onclick=()=>zoom(.8);$('#zoomOut').onclick=()=>zoom(1.25);$('#resetMap').onclick=()=>{stopMapTween(svg);box=[900,430,800,630];setBox();};svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89);},{passive:false});svg.onpointerdown=e=>{if(e.button!==0)return;stopMapTween(svg);svg.dataset.pressedBuilding=e.target.closest?.('[data-building]')?.dataset.building||'';pointers.set(e.pointerId,[e.clientX,e.clientY]);svg.setPointerCapture(e.pointerId);drag=[e.clientX,e.clientY];moved=false;};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(Math.hypot(e.clientX-old[0],e.clientY-old[1])>2)moved=true;if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch)zoom(pinch/d);pinch=d;drag=null;}else if(drag){const r=svg.getBoundingClientRect(),scale=Math.max(box[2]/r.width,box[3]/r.height);box[0]-=(e.clientX-drag[0])*scale;box[1]-=(e.clientY-drag[1])*scale;drag=[e.clientX,e.clientY];setBox();}};svg.onpointerup=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;if(moved)return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());if(state.pick){const geo=mapToGeo(p);if(!inCampus(geo)){toast(t('请在主校园区域内选择参考点。','Choose a point within the main campus.'));return;}state.origin={...geo,x:p.x,y:p.y,name:'Map reference',zh:'地图参考点'};state.pick=false;render();return;}const selectedBuilding=svg.dataset.pressedBuilding;svg.dataset.pressedBuilding='';if(selectedBuilding)showBuilding(selectedBuilding);};svg.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;};
function renderMap(){const active=state.selected?bOf(state.selected):null;$('#markers').innerHTML=buildings.map(b=>{let short=b.name.replace('Teaching and Learning Building','Teaching & Learning').replace(' Building','').replace('Aston Webb – Great Hall','Aston Webb');const left=b.id==='R30',width=short.length*7+50,dx=left?-width-12:12;return `<g class="map-pin ${active?.id===b.id?'selected':''}" transform="translate(${b.x} ${b.y})" data-building="${b.id}" tabindex="0" role="button" aria-label="${esc(t('查看 ','View ')+b.name)}"><circle r="8"/><rect x="${dx}" y="-18" rx="2" width="${width}" height="28"/><text x="${dx+10}" y="1">${esc(b.id+' · '+short)}</text></g>`;}).join('');$('#markers').querySelectorAll('g').forEach(g=>g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showBuilding(g.dataset.building);}});const o=state.origin,p=o&&(o.x!==undefined?o:geoToMap(o));$('#originMarker').innerHTML=p?`<g transform="translate(${p.x} ${p.y})"><circle class="origin-halo" r="18"/><circle class="origin-dot" r="6"/></g>`:'';$('#mapConnection').innerHTML=active&&p&&demo()?`<path class="clue-path" d="M${p.x} ${p.y} Q${p.x-50} ${active.y+55} ${active.x} ${active.y}"/><circle class="destination-ring" cx="${active.x}" cy="${active.y}" r="19"/>`:'';$('#mapMemo').innerHTML=active?`${esc(name(active))}<br><small>${esc(state.selected?floor(state.selected):'')}</small>`:t('点击图钉，<br>展开那栋楼的故事。','Pick a pin.<br>Open a little possibility.');$('#mapHint').hidden=!state.pick;$('#mapHint').textContent=t('点击学校地图设置参考起点；可拖动或缩放。','Tap the campus map to set a reference origin; pan and zoom are available.');if(!$('#indoorMap').hidden)renderIndoor();}
function renderIndoor(){const p=state.guide||state.selected;if(!p){$('#indoorMap').innerHTML=`<div class="indoor-empty"><span class="handwritten">${t('先找到一条线索。','Start with a little clue.')}</span><p>${t('选择教室或厕所，展开它的楼层档案。','Select a room or toilet to open its floor file.')}</p><button id="indoorExample" class="outline">${t('打开教室 404','Open Room 404')}${icon('arrow')}</button></div>`;$('#indoorExample').onclick=()=>openPlace('library404');return;}if(!demo()){$('#indoorMap').innerHTML=`<div class="indoor-empty"><p class="eyebrow">SOURCE VIEW</p><h3>${esc(floor(p))}</h3><p>${t('资料查看模式不显示假设室内图。','Source view does not display an assumed indoor plan.')}</p>${sourceInfo(p)}</div>`;return;}const viaLift=state.stepFree;$('#indoorMap').innerHTML=`<div class="indoor-label"><span>${esc(bOf(p).name)}</span><strong>${esc(floor(p))}</strong><small>${t('示意楼层图 · 非真实建筑平面图','ILLUSTRATIVE FLOOR PLAN · NOT AN ACTUAL BUILDING PLAN')}</small></div><svg class="floor-sketch" viewBox="0 0 660 380" role="img" aria-label="${esc(t('演示室内图：入口、电梯、楼梯及目标地点','Scenario indoor sketch: entrance, lift, stairs and destination'))}"><defs><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v8" stroke="#b7b19d" stroke-width="1"/></pattern></defs><path class="floor-shell" d="M70 75H590V315H70Z"/><path class="room-shape" d="M70 75H200V175H70ZM220 75H365V175H220ZM385 75H590V175H385ZM70 225H200V315H70ZM220 225H365V315H220ZM385 225H590V315H385Z"/><path class="indoor-path" d="${viaLift?'M130 275V205H445V125':'M290 275V205H445V125'}"/><rect class="target-room" x="385" y="75" width="205" height="100"/><text x="489" y="113" class="room-target-text" text-anchor="middle">${esc(p.type==='room'?p.name.split('·').at(-1).trim():t('厕所','TOILET'))}</text><text x="489" y="143" text-anchor="middle">${t('目标地点','DESTINATION')}</text><text x="130" y="265" text-anchor="middle">${t('电梯','LIFT')}</text><text x="290" y="265" text-anchor="middle">${t('楼梯','STAIRS')}</text><text x="130" y="125" text-anchor="middle">${t('示例房间','ROOM A')}</text><text x="290" y="125" text-anchor="middle">${t('示例房间','ROOM B')}</text><text x="489" y="275" text-anchor="middle">${t('示例房间','ROOM C')}</text><circle class="indoor-start" cx="${viaLift?130:290}" cy="275" r="7"/><circle class="indoor-destination" cx="445" cy="125" r="7"/></svg><div class="indoor-caption"><span class="red-pin"></span><span>${viaLift?t('演示路径经过电梯','Scenario path uses the lift'):t('演示路径经过楼梯','Scenario path uses the stairs')} · ${t('用于讨论导航界面，不用于实际找路','For testing the interface, not finding a real room')}</span></div>`;}
function switchMap(inside){$('#outdoorMap').hidden=inside;$('#indoorMap').hidden=!inside;$('#indoorTab').classList.toggle('active',inside);$('#outdoorTab').classList.toggle('active',!inside);if(inside)renderIndoor();animateMapStage(inside);}
$('#outdoorTab').onclick=()=>switchMap(false);$('#indoorTab').onclick=()=>switchMap(true);$('#pickOrigin').onclick=()=>{state.pick=!state.pick;switchMap(false);renderMap();};$('#exampleRoom').onclick=()=>openPlace('library404');$('#search').oninput=e=>{state.query=e.target.value;render();};$('#searchForm').onsubmit=e=>{e.preventDefault();state.query=$('#search').value;render();};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;if(state.category!=='toilet'){state.accessible=false;state.neutral=false;$('#accessible').checked=false;$('#neutral').checked=false;}render();});$('#accessible').onchange=e=>{state.accessible=e.target.checked;render();};$('#neutral').onchange=e=>{state.neutral=e.target.checked;render();};$('#changeOrigin').onclick=()=>$('#originDialog').showModal();$('#setOrigin').onclick=()=>{state.origin=$('#originSelect').value==='green'?{...scenarioOrigin}:{...buildings.find(b=>b.id===$('#originSelect').value)};$('#originDialog').close();render();};
function openScope(){$(`input[name="mode"][value="${state.mode}"]`).checked=true;$('#scopeDialog').showModal();}$('#scopeButton').onclick=openScope;$('#footerScope').onclick=openScope;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#acceptScope').onclick=()=>{const mode=$('input[name="mode"]:checked').value;if(mode!==state.mode){stopTimers();state.guide=null;$('#arrivalPrompt').hidden=true;if(state.selected)location.hash='/place/'+state.selected.id;}state.mode=mode;try{sessionStorage.setItem('clue:mode',mode);}catch{}if(state.selected)state.selected=byId(state.selected.id);$('#scopeDialog').close();try{sessionStorage.setItem('clue:briefed','1');}catch{}render();if(state.view==='about')renderAbout();switchMap(false);};$('#saveFeedback').onclick=()=>{const text=$('#feedbackText').value.trim();if(!text){$('#feedbackText').focus();return;}state.feedback.push({place:state.selected?.id||null,text,mode:state.mode,at:new Date().toISOString()});$('#feedbackDialog').close();$('#feedbackText').value='';toast(t('反馈已保留于本次演示，未发送给学校。','Feedback kept in this demonstration; not sent to the university.'));};
function mobileMapLabel(open){$('#mobileMapToggle').innerHTML=icon(open?'close':'pin')+(open?t('返回档案','Back to file'):t('打开地图','Open map'));}$('#mobileMapToggle').onclick=()=>{const open=$('#boardPage').classList.toggle('mobile-map-open');mobileMapLabel(open);};
function renderAbout(){$('#aboutPage').innerHTML=`<div class="about-heading"><p class="eyebrow">THE DESIGN BEHIND THE CASE</p><h1>${t('一份设计提案。<br><em>一张更好用的线索板。</em>','A design proposal.<br><em>A better trail to follow.</em>')}</h1><p>${t('Clue 关注校园里的小地点查找：从建筑，到楼层，再到真正要去的地方。探案感服务于探索与记忆，不增加完成任务的难度。','Clue focuses on the small places within campus: building, floor and the actual destination. Its detective-board character supports curiosity and recall without adding puzzles to essential tasks.')}</p></div><div class="about-grid"><article class="paper"><span>01 / EXPERIENCE</span><h2>${t('体验完整流程','Explore a complete journey')}</h2><p>${t('默认以完善后端为设计前提：搜索、附近设施、楼层图、通行偏好与主动提醒可以连贯体验；它们是可测试的前端情境。','The concept assumes a complete backend, connecting search, nearby facilities, floor sketches, access preferences and proactive prompts into a testable frontend scenario.')}</p></article><article class="paper"><span>02 / REALITY</span><h2>${t('真实能力集中说明','Keep the real scope clear')}</h2><p>${t('真实实现包括前端搜索、地图、筛选、收藏和页面状态。没有连接室内定位、完整房间库、可通行路径、实时开放状态或消息服务。','The frontend implements search, map interaction, filtering, bookmarks and page states. No indoor-positioning, complete directory, routing, live availability or messaging service is connected.')}</p><button class="text-button" id="aboutScope">${t('打开能力与假设说明','Open reality & assumptions')} ↗</button></article><article class="paper"><span>03 / CONTROL</span><h2>${t('让主动性有分寸','A timely clue, with control')}</h2><p>${t('选择地点后可授权体验到楼提醒。模拟事件触发下一步建议，使用者可以暂缓、暂停或静音。没有后台追踪；演示不申请真实 GPS 权限。','Opt into an approach prompt when selecting a place. A simulated event suggests the next step; snooze, pause or mute it. No background tracking or real GPS permission is requested.')}</p></article><article class="paper"><span>04 / EVIDENCE</span><h2>${t('设计假设与用户证据分开','Separate assumptions from evidence')}</h2><p>${t('视觉方向与“假设后端完善”的方式来自项目需求，不是用户研究结论。仍需问卷、访谈、现场观察和任务测试来检验清晰度、效率、可接受性与无障碍体验。','The visual direction and assumed-backend approach are design choices, not user-study findings. Questionnaires, interviews, field observation and task tests are still needed to evaluate clarity, effort, acceptance and accessibility.')}</p></article></div><h2>${t('公开资料与地图来源','Public directory & map sources')}</h2><div class="source-list">${Object.values(sources).map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('')}</div><p class="small">${t('公开资料查阅于','Sources consulted')} ${checked} · ${t('地图图像继承提供的校园地图。演示层不改写原始资料。','Map artwork comes from the supplied campus map. Scenario data does not overwrite the original directory.')}</p><p class="small">${t('收藏 ID 保存在本浏览器；反馈仅保留于当前页面。没有上传个人课表、位置或密钥。','Bookmark IDs are stored in this browser; feedback stays in this page session. No personal timetable, location or secrets are uploaded.')}</p>`;$('#aboutScope').onclick=openScope;}
function route(){const parts=location.hash.replace(/^#\/?/,'').split('/'),page=parts[0]||'find';if(page!=='guide'&&state.guide){stopTimers();state.guide=null;$('#arrivalPrompt').hidden=true;}if(['place','guide'].includes(page)&&byId(parts[1])){state.selected=byId(parts[1]);if(page==='guide'&&!state.guide){state.guide=state.selected;state.stage=0;}}else{state.selected=null;state.view=['saved','about'].includes(page)?page:'find';}const about=state.view==='about'&&!state.selected;$('#boardPage').hidden=about;$('#aboutPage').hidden=!about;$('#mobileMapToggle').hidden=about;if(about)renderAbout();render();window.scrollTo({top:0,behavior:'instant'});}
setupExplorer({en,onPeriod:value=>{state.period=value;render();},onReset:resetExplorer});
window.addEventListener('hashchange',route);window.addEventListener('pagehide',stopTimers);route();
let briefed=false;try{briefed=sessionStorage.getItem('clue:briefed')==='1';}catch{}
playEntrance({en,onFinish:()=>{if(!briefed&&!$('#scopeDialog').open)openScope();}});
